INSERT INTO public.checklist_secoes (id, modelo_versao_id, secao_key, titulo, ordem) VALUES
  ('375082df-ce07-5c7f-ab2b-1b3ec7dce205', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'edificacao', 'Edificação, Instalações, Equipamentos, Móveis e Utensílios', 1),
  ('db9b603a-652f-579e-ad31-381dffc34498', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'higienizacao', 'Higienização de Instalações, Equipamentos, Móveis e Utensílios', 2),
  ('9e372b25-2f82-589d-ac67-17cf6015d180', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'pragas', 'Controle Integrado de Vetores e Pragas Urbanas', 3),
  ('f4b8109e-6f57-5258-8926-7a5f1d746e29', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'agua', 'Abastecimento de Água', 4),
  ('25aea4b9-6bdc-5b13-8aee-bbb443afdf07', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'residuos', 'Manejo dos Resíduos', 5),
  ('172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'manipuladores', 'Manipuladores', 6),
  ('4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'materias-primas', 'Matérias-Primas, Ingredientes e Embalagens', 7),
  ('610a2543-7630-5d81-abbf-92f402b2ab8c', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'preparacao', 'Preparação do Alimento', 8),
  ('d6aa4367-e2ac-5105-8449-366d503749d3', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'armazenamento-transporte', 'Armazenamento e Transporte do Alimento Preparado', 9),
  ('511c94b9-e693-599d-96e1-e8f69311c544', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'exposicao', 'Exposição ao Consumo do Alimento Preparado', 10),
  ('86f460d8-acda-5101-ac4e-2638deb29101', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'documentacao', 'Documentação e Registro', 11),
  ('0b443acf-cbf9-5d3f-90a8-8b5f77bf960f', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'responsabilidade', 'Responsabilidade', 12)
INSERT INTO public.checklist_itens (id, modelo_versao_id, secao_id, item_key, texto, critico, ordem) VALUES
  ('b834ab11-ff4d-57e8-bd63-bc7f6cbe113f', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.1', 'Fluxo ordenado, sem cruzamentos em todas as etapas da preparação de alimentos.', false, 1),
  ('8e21713c-c665-5053-b5dc-52485c6c8d92', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.1b', 'Acesso às instalações controlado e independente, não comum a outros usos.', false, 2),
  ('072c9ff9-45c9-54dc-bc23-d5213fe0ac6c', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.2', 'Dimensionamento da edificação compatível com todas as operações; separação entre atividades por meios físicos ou outros eficazes, evitando contaminação cruzada.', false, 3),
  ('0237b185-539f-578c-94e1-aa7573e0b901', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.3', 'Piso, parede e teto com revestimento liso, impermeável e lavável.', false, 4),
  ('a2e0efb5-f80f-5a7b-851d-794edd586f9f', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.3b', 'Piso, parede e teto íntegros e conservados — sem rachaduras, trincas, goteiras, vazamentos, infiltrações, bolor ou descascamento.', false, 5),
  ('1e204ddc-c3e5-5174-b749-96ac16d22ae6', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.4', 'Portas e janelas ajustadas aos batentes.', false, 6),
  ('9d3db14b-0382-532b-8a87-bd785d19c95c', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.4b', 'Portas da área de preparação/armazenamento com fechamento automático.', false, 7),
  ('c9dc9d86-bb17-56ca-baff-94220d575ae2', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.4c', 'Aberturas externas (inclusive exaustão) com telas milimetradas removíveis contra vetores e pragas.', false, 8),
  ('e8db02ae-9459-56ac-9cb1-d5ced1d414f2', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.5', 'Instalações abastecidas de água corrente, com conexão a rede de esgoto ou fossa séptica.', false, 9),
  ('e9655ae0-151d-59a1-8c20-99d8e44b5ad1', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.5b', 'Ralos sifonados e grelhas com dispositivo de fechamento, quando existentes.', false, 10),
  ('b96c0c8f-3cc9-5a10-b3cf-470b527ec284', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.6', 'Caixas de gordura e esgoto com dimensão compatível, localizadas fora da área de preparação/armazenamento, em adequado estado de conservação e funcionamento.', false, 11),
  ('1a9ac16d-50f3-5230-838e-d7d26344f618', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.7', 'Áreas internas e externas livres de objetos em desuso, sem presença de animais.', false, 12),
  ('eb54ba45-40d8-5979-924c-09522d24393b', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.8', 'Iluminação da área de preparação adequada, sem comprometer higiene e características sensoriais dos alimentos.', false, 13),
  ('3199898e-c4c9-5cae-bb38-52b495031cfa', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.8b', 'Luminárias sobre a área de preparação protegidas contra explosão e quedas acidentais.', false, 14),
  ('c7aca638-5302-518e-83ec-53fbb2c86d1f', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.9', 'Instalações elétricas embutidas ou protegidas em tubulações externas íntegras.', false, 15),
  ('63c9c464-e77f-5fa0-bf93-e2656322c503', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.10', 'Ventilação garante renovação do ar e ambiente livre de fungos, gases, fumaça, pó e condensação.', false, 16),
  ('094e757a-4e9f-5ce1-b316-6ecaa0f09f57', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.10b', 'Quando existente equipamento ou sistema capaz de gerar fluxo de ar sobre a área de preparação (climatização, ventilação forçada ou exaustão direcionada), esse fluxo não incide diretamente sobre os alimentos expostos.', false, 17),
  ('5f2e89d7-e4ca-52cb-ab77-0f5fcb3c8cfe', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.11', 'Equipamentos e filtros de climatização conservados, com limpeza/troca/manutenção registradas (quando existente sistema de climatização).', false, 18),
  ('c7269a75-8fa8-5e18-b0fd-5bb94b215cd1', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.12', 'Instalações sanitárias e vestiários sem comunicação direta com área de preparação/armazenamento/refeitório.', false, 19),
  ('fe3df67e-d09e-5cd0-be22-94b3e6b795f5', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.12b', 'Instalações sanitárias organizadas e conservadas, com portas externas de fechamento automático.', false, 20),
  ('d300f707-79fd-5132-8a47-eee0ddea84d7', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.13', 'Instalações sanitárias com lavatórios, papel higiênico, sabonete líquido inodoro (anti-séptico ou com produto anti-séptico) e sistema de secagem das mãos.', false, 21),
  ('acf9cfec-506d-57a8-86f1-1076df44ad97', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.13b', 'Coletores de resíduos das instalações sanitárias com tampa acionada sem contato manual.', false, 22),
  ('7e20e65a-10ad-5acf-bb8a-224df67e8d9f', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.14', 'Lavatórios exclusivos para higiene das mãos na área de manipulação, em posição estratégica e número suficiente.', false, 23),
  ('0ad4769a-393c-5436-ab16-12e9ac4d7288', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.14b', 'Lavatórios da área de manipulação com sabonete líquido inodoro (anti-séptico), papel toalha e coletor acionado sem contato manual.', false, 24),
  ('210046ae-6ce2-527d-94f6-5998d8fd97e5', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.15', 'Equipamentos, móveis e utensílios em contato com alimentos de materiais que não transmitem substâncias tóxicas, odores ou sabores.', false, 25),
  ('17cff9da-eadd-54e4-9940-f4312055e224', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.15b', 'Equipamentos, móveis e utensílios em adequado estado de conservação, resistentes à corrosão e a higienizações repetidas.', false, 26),
  ('605325f2-330f-50d4-b986-c8e819a6c0c4', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.16', 'Manutenção programada e periódica de equipamentos/utensílios, com registro.', false, 27),
  ('d4438aaf-e8c9-5502-b4e2-526adcfe1053', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.16b', 'Calibração de instrumentos/equipamentos de medição, com registro (quando existentes instrumentos sujeitos a calibração).', false, 28),
  ('54af1cc1-35a6-5d13-af55-8bcd244c3de1', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '375082df-ce07-5c7f-ab2b-1b3ec7dce205', '1.17', 'Superfícies de equipamentos, móveis e utensílios lisas, impermeáveis, laváveis, sem rugosidades, frestas ou imperfeições.', false, 29),
  ('f16b6ea7-1907-548e-bc94-ff901e9e7326', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'db9b603a-652f-579e-ad31-381dffc34498', '2.1', 'Instalações, equipamentos, móveis e utensílios higienizados por funcionários capacitados, com frequência que garanta condições apropriadas.', false, 30),
  ('fac2fb0d-e8e7-5d60-a26f-29fc2169c167', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'db9b603a-652f-579e-ad31-381dffc34498', '2.2', 'Caixas de gordura limpas periodicamente, com descarte de resíduos conforme legislação.', false, 31),
  ('0fff3951-efa7-5716-9deb-79db65ce58bf', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'db9b603a-652f-579e-ad31-381dffc34498', '2.3', 'Operações de limpeza/desinfecção não rotineiras são registradas.', false, 32),
  ('bdc81209-2e98-5c83-9d02-6b15a6ba5e72', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'db9b603a-652f-579e-ad31-381dffc34498', '2.4', 'Área de preparação higienizada quantas vezes necessário e imediatamente após o término do trabalho, com precauções contra contaminação por saneantes/aerossóis.', false, 33),
  ('b211352f-e4d0-5a12-947f-78a1621d2c54', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'db9b603a-652f-579e-ad31-381dffc34498', '2.4b', 'Ausência de substâncias odorizantes/desodorantes nas áreas de preparação e armazenamento.', false, 34),
  ('656d009e-50aa-52eb-a88d-6dc75006d5da', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'db9b603a-652f-579e-ad31-381dffc34498', '2.5', 'Produtos saneantes regularizados pelo Ministério da Saúde, usados conforme instruções do fabricante, identificados e guardados em local reservado.', false, 35),
  ('97417ed7-83f2-5e61-aa36-2c3c03bba563', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'db9b603a-652f-579e-ad31-381dffc34498', '2.6', 'Utensílios/equipamentos de higienização próprios, conservados, em número suficiente, guardados em local reservado, distintos dos usados em partes em contato com alimento.', false, 36),
  ('25028e9a-f1fd-5916-a0bf-2abc342f2b99', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'db9b603a-652f-579e-ad31-381dffc34498', '2.7', 'Funcionários da higienização de instalações sanitárias usam uniformes diferenciados dos usados na manipulação de alimentos.', false, 37),
  ('b5c26afe-6956-5354-a90a-e2ff5fc99652', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '9e372b25-2f82-589d-ac67-17cf6015d180', '3.1', 'Edificação, instalações, equipamentos e utensílios livres de vetores e pragas urbanas, com ações contínuas de controle.', false, 38),
  ('f1e36f06-3228-57a8-b5d7-76961ec420b3', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '9e372b25-2f82-589d-ac67-17cf6015d180', '3.2', 'Quando a prevenção não é eficaz, controle químico executado por empresa especializada com produtos regularizados.', false, 39),
  ('e2f1435c-ac0d-5cdc-8a3e-b818d6b17917', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '9e372b25-2f82-589d-ac67-17cf6015d180', '3.3', 'Empresa especializada estabelece procedimentos pré/pós-tratamento; equipamentos/utensílios higienizados antes de reutilizar (quando há controle químico).', false, 40),
  ('fbb6506b-405d-5232-b30c-4643062f58e2', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'f4b8109e-6f57-5258-8926-7a5f1d746e29', '4.1', 'Uso exclusivo de água potável na manipulação de alimentos.', true, 41),
  ('24797fa9-d9ff-56f8-a776-60588338fa59', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'f4b8109e-6f57-5258-8926-7a5f1d746e29', '4.1b', 'Solução alternativa de abastecimento com potabilidade atestada semestralmente por laudo laboratorial (quando a fonte não é rede pública).', false, 42),
  ('5f80234f-6c96-5d9b-98a3-b7da64b9c6b0', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'f4b8109e-6f57-5258-8926-7a5f1d746e29', '4.2', 'Gelo fabricado a partir de água potável, mantido em condição que evite contaminação (quando utilizado gelo).', false, 43),
  ('28866345-d8d8-52a5-b1c0-f3cc844e95f3', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'f4b8109e-6f57-5258-8926-7a5f1d746e29', '4.3', 'Vapor em contato com alimentos/superfícies produzido a partir de água potável (quando utilizado vapor).', false, 44),
  ('d4ff04f3-708f-550e-8994-ad49386ab119', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'f4b8109e-6f57-5258-8926-7a5f1d746e29', '4.4', 'Reservatório de água íntegro, tampado, em adequada condição de conservação e higiênica — sem vedação comprometida, contaminação visível ou infiltração (quando existente reservatório/caixa d''água).', true, 45),
  ('a9d8866d-b1d2-5a74-a110-9c902dadb730', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'f4b8109e-6f57-5258-8926-7a5f1d746e29', '4.4b', 'Reservatório higienizado em intervalo máximo de 6 meses, com registro da execução (quando existente reservatório/caixa d''água).', false, 46),
  ('807c7ce6-bd74-5cc5-9023-8e4f5547adf7', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '25aea4b9-6bdc-5b13-8aee-bbb443afdf07', '5.1', 'Recipientes de resíduos identificados, íntegros, de fácil higienização/transporte, em número/capacidade suficientes.', false, 47),
  ('c7b134be-ab29-54a0-a237-a4bd066a1373', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '25aea4b9-6bdc-5b13-8aee-bbb443afdf07', '5.2', 'Coletores da área de preparação/armazenamento com tampa acionada sem contato manual.', false, 48),
  ('e5e52134-294f-56cf-8df1-3d6da5ef7232', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '25aea4b9-6bdc-5b13-8aee-bbb443afdf07', '5.3', 'Resíduos coletados frequentemente e estocados em local fechado e isolado da área de preparação/armazenamento.', false, 49),
  ('f364eccc-1617-5da8-a551-986e942db602', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.1', 'Controle de saúde dos manipuladores registrado, conforme legislação específica.', false, 50),
  ('829a6044-197a-5a6e-aa7b-0caf5042bb2f', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.2', 'Manipuladores com lesões/sintomas que comprometam a qualidade higiênico-sanitária afastados da preparação enquanto persistir.', true, 51),
  ('66a3607e-5977-5877-a8a2-1b2c19d6b074', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.3', 'Manipuladores com asseio pessoal, uniformes compatíveis, conservados e limpos, trocados no mínimo diariamente, de uso exclusivo interno.', false, 52),
  ('b34b65d8-040d-559f-8b25-c9e19c2d1586', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.3b', 'Roupas e objetos pessoais guardados em local específico e reservado.', false, 53),
  ('13293d0d-b4f3-5035-bdec-bad7785afd90', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.4', 'Manipuladores lavam as mãos ao chegar, antes/depois de manipular alimentos, após interrupções, contato com material contaminado, uso de sanitários e sempre que necessário.', true, 54),
  ('a7450be9-de8c-5529-8f08-df8d8cbc74b1', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.4b', 'Cartazes de orientação sobre lavagem/anti-sepsia das mãos afixados em locais visíveis, inclusive sanitários e lavatórios.', false, 55),
  ('aae4d034-2486-58bc-a53b-1513a3dd7e00', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.5', 'Manipuladores não fumam, falam desnecessariamente, cantam, assobiam, espirram, cospem, tossem, comem, manipulam dinheiro ou praticam atos que contaminem o alimento durante a atividade.', false, 56),
  ('c0ffa2e6-073b-581b-8863-2fd79e9a28cd', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.6', 'Manipuladores com cabelos presos/protegidos, sem barba, unhas curtas sem esmalte/base, sem adornos ou maquiagem durante a manipulação.', false, 57),
  ('060ab735-9071-56a5-bd5e-7a5648c0dc05', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.7', 'Manipuladores supervisionados e capacitados periodicamente (higiene pessoal, manipulação higiênica, doenças transmitidas por alimentos), com comprovação documental.', false, 58),
  ('456a889e-397d-5b1d-94f1-aac3bffba5f6', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '172c4b19-a455-5b9f-a72c-e0e403e6ed7a', '6.8', 'Visitantes cumprem os mesmos requisitos de higiene e saúde exigidos dos manipuladores.', false, 59),
  ('d5aeb36d-dfd1-5231-81fd-a1c25869f760', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '7.1', 'Critérios de avaliação/seleção de fornecedores especificados; transporte em condições adequadas de higiene/conservação.', false, 60),
  ('d4984ef9-bf77-5f41-a0ed-381de72b4cd0', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '7.2', 'Recepção de matérias-primas/ingredientes/embalagens em área protegida e limpa, com medidas contra contaminação.', false, 61),
  ('5544aba7-06a8-5ee6-9943-74efe2088c7f', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '7.3', 'Matérias-primas, ingredientes e embalagens inspecionados e aprovados na recepção, conforme critérios pré-estabelecidos.', false, 62),
  ('c3bc51c1-2bb6-5385-b194-f1bebebd0166', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '7.3b', 'Embalagens primárias das matérias-primas/ingredientes recebidas íntegras, sem violação ou dano que comprometa a proteção do conteúdo.', false, 63),
  ('e589663a-1f07-5a45-9dbd-732b07e0c99d', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '7.3c', 'Temperatura de matérias-primas/ingredientes perecíveis verificada e registrada no recebimento (quando recebe perecíveis com exigência de controle de temperatura).', false, 64),
  ('dcda85c0-3077-5096-b4db-aaee0608cf88', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '7.4', 'Lotes reprovados ou vencidos devolvidos ao fornecedor ou identificados/armazenados separadamente, com destinação final determinada.', false, 65),
  ('ffbe2bd3-9321-52f1-b886-d4dc23bf1f81', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '7.5', 'Armazenamento em local limpo e organizado, protegido contra contaminantes, identificado, respeitando prazo de validade/ordem de entrada.', false, 66),
  ('f4a14cfe-3940-5104-b5aa-b1588aca775a', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '4b1ace1e-1b3e-5842-b7cd-1e75c784ccf8', '7.6', 'Armazenamento sobre paletes/estrados/prateleiras de material liso, resistente, impermeável e lavável, com espaçamento adequado.', false, 67),
  ('34ea97a7-efb9-5ffd-a4ef-3a48bdd8de7a', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.1', 'Matérias-primas, ingredientes e embalagens em condições higiênico-sanitárias adequadas para a preparação.', false, 68),
  ('7d5391d7-b238-5ded-bc01-8264ca2bf522', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.2', 'Quantitativo de funcionários, equipamentos, móveis/utensílios compatível com volume, diversidade e complexidade das preparações.', false, 69),
  ('ee82cbad-a778-5b7b-bf21-6b8eb8bc4ffe', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.3', 'Medidas para minimizar contaminação cruzada; sem contato direto/indireto entre crus, semipreparados e prontos para consumo.', true, 70),
  ('6cf1eb72-c569-5de5-81ed-e328eaa89c4e', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.4', 'Funcionários que manipulam alimentos crus lavam e fazem anti-sepsia das mãos antes de manusear alimentos preparados (quando o estabelecimento manipula alimentos crus antes de alimentos preparados).', true, 71),
  ('47d502f8-f060-5755-9a68-68f876b63f37', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.5', 'Matérias-primas/ingredientes perecíveis expostos à temperatura ambiente somente pelo tempo mínimo necessário.', false, 72),
  ('1069e555-2d66-54a7-a30e-eef41f696465', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.6', 'Sobras de matérias-primas/ingredientes acondicionadas e identificadas — produto, data de fracionamento, validade após abertura (quando há fracionamento).', false, 73),
  ('f93e1e82-f484-5f6c-99a4-c40579399980', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.7', 'Limpeza das embalagens primárias antes da preparação, quando aplicável.', false, 74),
  ('8f2c8859-528e-5a91-bcee-656078f533e9', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.8', 'Tratamento térmico atinge no mínimo 70 °C em todas as partes do alimento, ou combinação tempo/temperatura equivalente (quando o estabelecimento realiza tratamento térmico/cocção).', true, 75),
  ('fccf5cf1-d99c-5437-a97a-072ea5079d3d', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.9', 'Eficácia do tratamento térmico avaliada por temperatura/tempo e, quando aplicável, textura/cor (quando o estabelecimento realiza tratamento térmico/cocção).', false, 76),
  ('506e70c5-afaf-5b6b-8c13-a583078c0626', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.10', 'Para frituras, medidas garantem que óleo/gordura não sejam fonte de contaminação química (quando há fritura).', false, 77),
  ('2425be10-43b0-5728-8d7c-a5638b39c174', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.11', 'Óleos e gorduras aquecidos a no máximo 180 °C, substituídos ao primeiro sinal de alteração físico-química/sensorial (quando há fritura).', false, 78),
  ('22e3cf17-7701-5a12-b550-0323a2267f29', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.12', 'Alimentos congelados descongelados antes do tratamento térmico, salvo recomendação do fabricante para cocção ainda congelado (quando usa alimentos congelados).', false, 79),
  ('6b03e09e-a384-5198-bbbe-9301ed123bb9', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.13', 'Descongelamento sob refrigeração <5 °C ou em micro-ondas com cocção imediata (quando há descongelamento).', true, 80),
  ('8472a5b6-28d3-5772-9f3e-64939b3ea565', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.14', 'Alimentos descongelados mantidos sob refrigeração se não usados imediatamente; não recongelados (quando há descongelamento).', true, 81),
  ('a9ac7808-5fbc-5742-a3ab-52f2adc14159', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.15', 'Conservação a quente acima de 60 °C por no máximo 6 horas (quando há conservação a quente).', true, 82),
  ('bac0b67a-23ac-5363-91af-4f18608621e0', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.16', 'Resfriamento de 60 °C a 10 °C em até 2 horas, seguido de refrigeração <5 °C ou congelamento ≤ −18 °C (quando há resfriamento).', true, 83),
  ('2d444b11-3e0e-57f7-a753-6a1a118abff1', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.17', 'Prazo máximo de consumo sob refrigeração a 4 °C de 5 dias, reduzido se temperatura entre 4 °C e 5 °C (quando o estabelecimento conserva alimento preparado sob refrigeração).', true, 84),
  ('f6183aee-e2ed-5607-8e63-9a25e5ba6c2e', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.18', 'Alimento armazenado sob refrigeração/congelamento identificado (designação, data de preparo, validade), temperatura monitorada e registrada.', false, 85),
  ('8d178279-9816-5932-9a3c-e4f77065dd63', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.19', 'Alimentos consumidos crus submetidos a higienização com produtos regularizados, sem deixar resíduos (quando o estabelecimento serve alimentos crus).', false, 86),
  ('00e0cff7-7d55-555b-9be4-d665b1962171', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '610a2543-7630-5d81-abbf-92f402b2ab8c', '8.20', 'Controle e garantia da qualidade dos alimentos preparados implementado e documentado.', false, 87),
  ('a0afed51-6c7d-5789-9814-32afe6f112ac', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'd6aa4367-e2ac-5105-8449-366d503749d3', '9.1', 'Alimentos armazenados/aguardando transporte identificados (designação, data de preparo, validade) e protegidos contra contaminantes.', false, 88),
  ('fce4a1ee-b715-5748-aee8-7865c7ec5a0e', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'd6aa4367-e2ac-5105-8449-366d503749d3', '9.2', 'Armazenamento do alimento preparado em condições adequadas de tempo/temperatura, com temperatura monitorada (quando há armazenamento de alimento preparado antes da distribuição, exposição ou consumo).', true, 89),
  ('5d9705f3-b12b-5780-a7c8-4923624548a1', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'd6aa4367-e2ac-5105-8449-366d503749d3', '9.2b', 'Transporte do alimento preparado em condições adequadas de tempo/temperatura, com temperatura monitorada (quando há transporte).', true, 90),
  ('96a7fdcf-fd7d-5e2e-b148-ce37b7125be8', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'd6aa4367-e2ac-5105-8449-366d503749d3', '9.3', 'Meios de transporte higienizados, sem vetores/pragas, com cobertura de proteção da carga (quando há transporte).', false, 91),
  ('3ed33928-94d6-5b9d-9595-cc81b0f0c208', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', 'd6aa4367-e2ac-5105-8449-366d503749d3', '9.3b', 'Veículo não transporta outras cargas que comprometam a qualidade higiênico-sanitária do alimento (quando há transporte).', false, 92),
  ('24747e7a-30aa-5e35-ad74-1e626e3d6637', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '511c94b9-e693-599d-96e1-e8f69311c544', '10.1', 'Áreas de exposição/consumação organizadas e em adequadas condições, com equipamentos/móveis/utensílios compatíveis e em número suficiente (quando existente área de exposição/consumação).', false, 93),
  ('90c9fab7-e0ae-5d06-87d6-0b2a569c9c8c', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '511c94b9-e693-599d-96e1-e8f69311c544', '10.2', 'Manipuladores fazem anti-sepsia das mãos e usam utensílios ou luvas descartáveis na exposição (quando há operação de exposição/distribuição).', false, 94),
  ('ecbea566-f809-5ff8-abe0-ebb538bef95e', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '511c94b9-e693-599d-96e1-e8f69311c544', '10.3', 'Equipamentos de exposição/distribuição sob temperatura controlada dimensionados adequadamente, com temperatura monitorada (quando há exposição sob temperatura controlada).', false, 95),
  ('bf29c0cb-697c-5c78-9da5-beba4b921604', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '511c94b9-e693-599d-96e1-e8f69311c544', '10.4', 'Equipamento de exposição na consumação dispõe de barreiras de proteção contra contaminação pelo consumidor/outras fontes (quando há consumação local).', false, 96),
  ('c98d8b1c-0c1d-54be-9407-84ae76d28337', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '511c94b9-e693-599d-96e1-e8f69311c544', '10.5', 'Utensílios de consumação descartáveis ou, quando não-descartáveis, higienizados e armazenados em local protegido (quando há consumação local).', false, 97),
  ('10c7f1d1-13ef-5a72-a104-f1a89a8112f5', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '511c94b9-e693-599d-96e1-e8f69311c544', '10.6', 'Ornamentos e plantas na área de consumação não constituem fonte de contaminação (quando há ornamentos/plantas).', false, 98),
  ('0750bccf-475d-5f64-96c0-4dca12274948', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '511c94b9-e693-599d-96e1-e8f69311c544', '10.7', 'Área de recebimento de pagamento reservada; funcionários dessa atividade não manipulam alimentos (quando há recebimento de pagamentos no estabelecimento).', false, 99),
  ('73650aac-6f55-52d7-8049-b4dcbdd68a68', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '86f460d8-acda-5101-ac4e-2638deb29101', '11.1', 'Manual de Boas Práticas e POPs disponíveis, acessíveis aos funcionários e à autoridade sanitária.', false, 100),
  ('0e049bb5-7be3-5ea0-bad1-2da6ee492d5f', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '86f460d8-acda-5101-ac4e-2638deb29101', '11.2', 'POPs contêm instruções sequenciais, frequência de execução e responsáveis; aprovados, datados e assinados.', false, 101),
  ('4a0a9c58-65f5-59b2-91d4-a2d03d0bd520', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '86f460d8-acda-5101-ac4e-2638deb29101', '11.3', 'Registros mantidos por no mínimo 30 dias a partir da preparação.', false, 102),
  ('653c791a-20a9-5e54-8391-8d898535a61a', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '86f460d8-acda-5101-ac4e-2638deb29101', '11.4a', 'POP de higienização de instalações, equipamentos e móveis implementado.', false, 103),
  ('24bb5b59-9e4e-5b0f-855a-ea104efc8414', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '86f460d8-acda-5101-ac4e-2638deb29101', '11.4b', 'POP de controle integrado de vetores e pragas urbanas implementado.', false, 104),
  ('0505cfe8-75ee-5a5c-841e-90bf4e969cb0', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '86f460d8-acda-5101-ac4e-2638deb29101', '11.4c', 'POP de higienização do reservatório implementado.', false, 105),
  ('7ddb43f6-610d-55dc-b0dd-4252ff733b91', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '86f460d8-acda-5101-ac4e-2638deb29101', '11.4d', 'POP de higiene e saúde dos manipuladores implementado.', false, 106),
  ('b6c516e8-b2ad-52d7-8d71-19628d336f5b', '5d79474b-a83f-5a99-a3c8-b1c091d79bf5', '86f460d8-acda-5101-ac4e-2638deb29101', '11.5', 'POP de higienização de instalações especifica superfície, método, princípio ativo/concentração, tempo de contato e temperatura.', false, 107),
